"""Wrap the untouched Stockfish.js build as a string, so a Web Worker can be made from it.

    python js/vendor/make_stockfish_src.py path/to/stockfish.asm.js

A page opened from file:// cannot `new Worker("stockfish.js")` or fetch a file,
but it can build a worker from a Blob. So the engine ships as one string in
stockfish-src.js, loaded by an ordinary <script> tag. The string is the file
byte for byte; the SHA-256 printed here is the one README.md records, so the
wrapped copy can be checked against the published build.
"""
import hashlib, json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
src_path = sys.argv[1]
raw = open(src_path, "rb").read()
text = raw.decode("utf-8")
if "</script" in text.lower():
    raise SystemExit("the engine source contains </script, which would end an inlined <script> early")

body = json.dumps(text).replace("</", "<\\/")   # still the same string once parsed
out = ("/* Stockfish.js 10.0.2 (asm.js build), GPL-3.0 -- see STOCKFISH-COPYING.txt and README.md.\n"
       "   Generated by make_stockfish_src.py: the published stockfish.asm.js, unmodified, as a string.\n"
       "   sha256 of the wrapped file: " + hashlib.sha256(raw).hexdigest() + " */\n"
       "(function (root) { root.STOCKFISH_SOURCE = " + body + "; })"
       "(typeof window !== 'undefined' ? window : globalThis);\n")
open(os.path.join(HERE, "stockfish-src.js"), "w", encoding="utf-8", newline="\n").write(out)
print("wrote stockfish-src.js: %d KB, source sha256 %s" % (len(out.encode()) // 1024, hashlib.sha256(raw).hexdigest()))
